import{_ as a,C as r,o,c as n,j as e,a as s,E as l,a5 as i}from"./chunks/framework.DNkHA0lr.js";const b=JSON.parse('{"title":"对你现在的人生处境感到愤怒吧","description":"","frontmatter":{"title":"对你现在的人生处境感到愤怒吧","originalTitle":"Get Mad At Where You Are In Life","date":"2022-03-18","originalUrl":"https://thedankoe.com/letters/get-mad-at-where-you-are-in-life/","minutes":6,"sourceHash":"23acf5fe2e5ce080ad352e6a64512fbf7d4c6bf8b0b89ac241fa371116a09bb9","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/get-mad-at-where-you-are-in-life/"}]]},"headers":[],"relativePath":"letters/get-mad-at-where-you-are-in-life.md","filePath":"letters/get-mad-at-where-you-are-in-life.md"}'),d={name:"letters/get-mad-at-where-you-are-in-life.md"};function m(f,p,h,c,g,u){const t=r("ArticleMeta");return o(),n("div",null,[p[0]||(p[0]=e("h1",{id:"对你现在的人生处境感到愤怒吧",tabindex:"-1"},[s("对你现在的人生处境感到愤怒吧 "),e("a",{class:"header-anchor",href:"#对你现在的人生处境感到愤怒吧","aria-label":'Permalink to "对你现在的人生处境感到愤怒吧"'},"​")],-1)),l(t),p[1]||(p[1]=i('<p><a href="https://www.youtube.com/embed/eMeacfNkpzE?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><a href="https://open.spotify.com/embed/episode/4EOOaN7gyE33tnYfRvOdTt?si=gmVMtf70QGSnSPOeSzPhCQ&amp;utm_source=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>认识一下吉米。</p><p>吉米是个普通男人。</p><p>他上学，找了份体面的工作，做了社会告诉他应该做的一切。</p><p>吉米开心了一阵子，但在经历了现代生活单调的重复之后，他陷入了墨守成规的泥潭。</p><p>优步外卖（Uber Eats）。色情片。电子游戏。网飞（Netflix）。Reddit论坛。速冻卷饼（Hot Pockets）。</p><p>你懂的，如果你是有意识地偶尔做一次，这些事情其实没那么糟……但如果是无意识地沉溺其中，30年的平庸岁月转瞬即逝。</p><p>有人向吉米伸出了援手。</p><p>宇宙给了他一个机会。</p><p>一种感觉。一次冒险的召唤。一个更高阶的自己正在乞求……尖叫着想要冲破牢笼。</p><p>他甚至都没注意到。</p><p>吉米拿起遥控器，点击“跳过片头”，猛吸了一口水烟筒，然后在迷迷糊糊中醒来，只为了穿上他的工作服。</p><h2 id="万物皆心智" tabindex="-1"><strong>万物皆心智</strong> <a class="header-anchor" href="#万物皆心智" aria-label="Permalink to &quot;**万物皆心智**&quot;">​</a></h2><p>吉米是一个概念，是你读到这里时创造出来的。</p><p>当你停下来，吉米就不复存在了。</p><p>你的注意力是介于吉米和虚无之间的屏障。</p><p>“我很害怕，”吉米说。</p><p><em>噗——消失了。</em></p><p>你可能听过精神导师和哲学家提到，宇宙是一个巨大的心智。</p><p>怎么会这样呢？</p><p>嗯，心智通过概念、故事、隐喻和符号来理解这个世界。</p><p>要理解这些概念，我们需要理解使之成为概念的概念网络。</p><p>为什么你的手是一只手？如果没有手臂，它还是一只手吗？那杯子呢？如果没有手去拿起它，那个杯子是否毫无意义？</p><p>那引力呢？引力他妈的到底是个什么东西？如果不理解力、引力常数、物体的质量以及质量中心之间的距离，你能理解引力吗？你如何确定一个物体的质量？如果没有内和外，能存在一个质量的“中心”吗？</p><p>你所知道的一切，只是一层层为了让你理解而拼凑起来的故事。</p><p>如果这封邮件是用中文写的，对你来说有意义吗？没有。</p><p>心智通过故事来理解生活并赋予其意义。</p><p><em>“酷，Dan，明白了。非常有见地，巴拉巴拉，叮叮当当，一堆词，概念，故事”</em></p><p>故事赋予生命意义。</p><p>你的身份就是你讲给自己的故事。如果你没有意识到这一点，你就会按照自动驾驶模式活出那个故事。如果不将其意识化，它绝对不可能以对你有利的方式结局。</p><p>你是英雄还是反派？</p><p>两者缺一不可。</p><p>没有“反派”这个概念，“英雄”这个概念就没有意义。</p><p>这些对立的概念反映了极性法则。它们创造了张力。</p><p>如果没有“苦难”，“生命”的概念就毫无意义。</p><p>至于这些是被贴上“好”还是“坏”的标签，取决于你自己。</p><p>记住，这都是一个故事。一场游戏。一切都在你的掌控之中。一切皆在你的脑海中。</p><p>生命意味着苦难。这种苦难是否对你产生负面影响，取决于你的意识水平和期望。</p><p>如果你期望生命不包含苦难，那么你就会受苦。为什么？因为你在与现实抗争。你试图控制不可控的事物，而不是顺应它，并在这种洪流中控制你自己。</p><p>如果故事里没有英雄和反派，那它就很无聊。毫无意义。让人缺乏成就感。这个故事就不复存在了。</p><p>你是演员。是角色背后的玩家。是心智背后的意识。</p><p>生活是英雄和反派之间的一场舞蹈。</p><p>推与拉。无为。阴与阳。</p><p>善与恶的战斗是在生活中推动你走向任何方向的动力。如果你意识到了这场战斗，你就会向积极的方向前进。如果你无意识或者抗拒这场战斗，你就会向消极的方向滑落。</p><p>英雄出身卑微。英雄通过玩这场游戏来升级。他会失败……很多次，但他不会放弃。</p><p>他变得更强大。培养了高价值的技能。通过对人生的方向承担全部责任，他操纵了这场游戏，让局势对自己有利。</p><p>在与反派交手几回合后，他获胜了。他的名字被铭记。他给他人留下的影响被传颂几个世纪。他的遗产清晰可见。</p><h2 id="角色选择" tabindex="-1"><strong>角色选择</strong> <a class="header-anchor" href="#角色选择" aria-label="Permalink to &quot;**角色选择**&quot;">​</a></h2><p>你现在处于你理想中的人生位置了吗？</p><p>你拥有你想要的金钱、身体、精力和人际关系了吗？</p><p>你现在感到火大吗？</p><p>你是你故事里的主角吗？或者你只是一层认同那些对你毫无益处的负面特征的故事？</p><p>“我身无分文。”</p><p>“我是个大麻佬。”</p><p>“我不够好。”</p><p>“我骨瘦如柴且虚弱。”</p><p>你变成了你告诉自己的那个故事。</p><p>这强调了通过正确的校准来有意识地塑造身份的必要性。</p><p>引导你的思想、情感和行动，使之与你想成为的人保持一致。与你想要活出的故事保持一致。不要限制自己。</p><p>描绘你的愿景。</p><p>写下你的目标。</p><p>写下你的优先事项。</p><p><a href="https://shop.thedankoe.com/planner" target="_blank" rel="noreferrer">如果你还没有的话，使用 Power Planner（免费）。</a></p><p>理清你每天需要采取的那些显而易见的行动。</p><p>这他妈的很简单。</p><p>学习并应用。</p><p>他妈的去健身房吧。改变你那像小孩子一样的饮食习惯。开始创办你一直告诉自己要创办的企业。</p><p>不知道怎么做？去学。</p><p>看个YouTube视频，买门课程，问个朋友。看在老天的份上，你可以上网啊。这是一片充满无限潜力的土地，你却用它来刷梗图、看色情片、麻痹你的大脑。</p><p>有意识地审视你当前的生活状况，为你没有到达你想要的位置而感到愤怒吧。</p><p>在保持意识清醒的同时，将这种愤怒转化为构建伟大事业的动力。</p><p>将其视为一种你可以随时调用的能量源。</p><p>在你去健身房之前，愤怒起来。与你内心那个平庸的潜在自我——那个反派——去战斗。</p><p>在此时此刻与生活共舞，即使有数百磅的重物将你压垮。</p><p>垃圾食品？令人作呕。</p><p>色情片？舔狗才看。</p><p>任何低于卓越的东西？绝不接受。</p><p>如果你没有达到你理想中的人生位置并且缺乏意义，你必须变得极端化。</p><p>对你那些消极的人生选择感到无比厌恶，以至于光是想到参与那种活动，都觉得那会让你看起来像个白痴。</p><p>再次强调，这是一支舞。只有当你看不清“愤怒”和“邪恶”的本质时，它们才会成为问题。</p><p>当你失去意识时。当你沉睡时。当你盲目地在生活中漂流，还指望好运会自动掉到你腿上时。</p><p>去他妈的。</p><p>对你自己感到愤怒，击败那个试图把你拖下水的婊子般的声音。</p><p>保持脚踏实地，与真相建立连接，同时看清生活这场游戏的本质。然后以你有意识创造的角色来玩这场游戏。</p><p>每天。最少。1小时。</p><p><strong>1小时用于你的事业。</strong></p><p><strong>1小时用于你的健身。</strong></p><p><strong>1小时用于你的心理健康。</strong></p><p><em>你肌肉发达，富有，自信，而且你绝不接受任何低于这个标准的东西。</em></p><p>你他妈的到底有什么事做比这个更好？</p><p><strong>没有。</strong></p><p>一切皆在你的脑海中。</p><p>现在。就行动。</p><p><a href="https://www.modernmastery.co/community/modern-mastery-hq-special" target="_blank" rel="noreferrer">如果你还没加入MMHQ，赶快他妈的加进去。仅限这封信，加入只需5美元。</a></p><p>妈的。</p><p>DAN 撤了。</p><hr><p><a href="/en/letters/get-mad-at-where-you-are-in-life">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',99))])}const k=a(d,[["render",m]]);export{b as __pageData,k as default};
